/* lp_cal.h - the stock constants the READ-ONLY line-pressure / torque-
 * intervention shadows (app/lp_shadow.c, app/ti_shadow.c) read from BELOW
 * 0x80000, where our application overwrites the stock image (generated by
 * tools/gen_lp_cal.py; the host test lp_cal_bytes re-derives every table from
 * the stock image). Data at 0x80000 and above is read IN PLACE through
 * app/cal_inplace.h. (2026-11-20, ~/tcu_sweep/lp_ti_shadow_port.md) */
#ifndef TCU_APP_LP_CAL_H
#define TCU_APP_LP_CAL_H

#if defined(TCU_OUTPUT_PATH)
#error "the line-pressure shadow is read-only: an output path may not include lp_cal.h"
#endif

#include <stdint.h>

#define LP_CALP_N 48u
/* the cal pointer table 0x5CFD8 (*0xFFF84D70): cal + off -> the stock address of the value, off = 4 * i */
extern const uint32_t LP_CALP[LP_CALP_N];
#define LP_CALA(off) (LP_CALP[(off) / 4u])

extern const uint32_t LP_MAP[9];       /* the steady maps by 0x51DE0[idx], variant 0 (0x5CE3C chain) */
extern const uint32_t LP_HOT[9];       /* the reason-0x0C demand cell of that chain (0 = none) */
extern const uint8_t  LP_G51DE0[10];   /* 0x51DE0 */
extern const uint8_t  LP_UPIDX[81];    /* 0x51E08 [c27 + 9 c2d] */
extern const uint8_t  LP_DNIDX[81];    /* 0x51F4C */
extern const uint32_t LP_UPPTR[14];    /* 0x5CEC0 chain: 7 up types x {e3ed 0, 1} -> the s16 demand cell */
extern const uint32_t LP_DNPTR[18];    /* 0x5CF44 chain: 18 down types -> the s16 demand cell */
extern const uint16_t LP_E108[25];     /* the Sys curve (flash 0xE108): n, x[12], y[12] */
extern const int16_t  LP_E170[79];     /* the NO temperature map (flash 0xE170): nx, ny, x, y, z */
extern const uint8_t  LP_TI_CLASS[8];  /* 0x634D6: class by BD16 */
extern const uint8_t  LP_TI_PHASE[24]; /* 0x51C6C: phase by [step * 3 + class] */

#endif
